// HardGates returns the full canonical registry.
func HardGates() []Gate { return hardGates }

// ApplicableHardGates returns gates with a verified runtime producer
// (applicable subset; gates without producer cannot PASS per v2 §0.6.3).
func ApplicableHardGates() []Gate {
	var out []Gate
	for _, g := range hardGates {
		if g.ProducerStatus == "verified" {
			out = append(out, g)
		}
	}
	return out
}

// HardGateByName returns the gate with the given canonical metric name.
func HardGateByName(name string) (Gate, bool) {
	for _, g := range hardGates {
		if g.GateID == name {
			return g, true
		}
	}
	return Gate{}, false
}

// HardGateCount returns the number of gates in the canonical registry.
func HardGateCount() int { return len(hardGates) }

